__NUXT_JSONP__("/think-tanks/columnas/how_four_think_tanks_are_adapting_as_core_funding_declines", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M,N,O,P){return {data:[{post:{slug:"how_four_think_tanks_are_adapting_as_core_funding_declines",title:"How four think tanks are adapting as core funding declines",date:"2026-07-16T16:04:00.000Z",img:"https:\u002F\u002F429spfvz9e.ucarecd.net\u002Ffd1a878e-aba7-491d-a1db-72a56e9cd80f\u002F","img-alt":"Financiamiento ONG",autor:"Andrea Cabrera",medio:r,link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fhow-four-think-tanks-are-adapting-as-core-funding-declines\u002F",category:o,extracto:s,toc:[{id:t,depth:u,text:v},{id:w,depth:u,text:x}],body:{type:m,children:[{type:b,tag:d,props:{},children:[{type:a,value:"Most think tanks do not have stable core funding, nor will they even get it. Preliminary results from the "},{type:b,tag:j,props:{},children:[{type:b,tag:e,props:{href:"https:\u002F\u002Fonthinktanks.org\u002Fannouncement\u002Fthink-tank-state-of-the-sector-survey-2026\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"2026 State of the Sector Survey"}]}]},{type:a,value:" indicate that only 18% are funded primarily through core support. The remainder relies on project-based funding. Additionally, 70% of organisations operate on project grants lasting two years or less, which limits their ability to hire staff, develop research lines, or invest in new offices."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"As a result, organisations are actively seeking alternative sources of income. The survey shows that 29% now include service sales in their income mix, 18% include membership fees, and 10% report income from investments and rent. While none of these sources dominates, collectively they signal a shift: revenue streams once considered marginal are becoming increasingly important."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:s}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"At the 2026 OTT Conference in Rabat, the session "},{type:b,tag:j,props:{},children:[{type:a,value:"“Forget core funding: alternative"}]},{type:a,value:" "},{type:b,tag:j,props:{},children:[{type:a,value:"income streams for resilient think tanks”"}]},{type:a,value:" brought together four leaders to discuss their organisations’ approaches. This session provided a candid examination of how four funding models operate in practice."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The conversation was convened by Jorge Morel ("},{type:b,tag:e,props:{href:"https:\u002F\u002Fiep.org.pe\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Instituto de Estudios Peruanos"}]},{type:a,value:", IEP, Peru), Liliana Alvarado ("},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.ethos.org.mx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:y}]},{type:a,value:", Mexico), Anthea Haryoko ("},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.cips-indonesia.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"CIPS"}]},{type:a,value:", Indonesia) and Margarita Beneke de Sanfeliu ("},{type:b,tag:e,props:{href:"https:\u002F\u002Ffusades.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"FUSADES"}]},{type:a,value:", El Salvador)."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"None of the four organisations began by creating something entirely new. Instead, they identified their existing strengths and considered who might be willing to pay for those capabilities."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"IEP leveraged its reputation and methodological expertise by establishing a public opinion survey unit in 2019, initially supported by the Ford Foundation’s BILD programme. During the pandemic, the Institute transitioned to telephone surveys, capitalising on Peru’s high mobile penetration. IEP is now the country’s second most recognised polling firm after Ipsos, with election-time accuracy that has built significant credibility. Its competitive advantage lies in methodological rigour and official registration, not pricing. IEP has successfully marketed its expertise in social science to the media, international organisations, and private clients."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Ethos aims to position foundations as clients rather than solely as donors. Liliana outlined a pilot model offering consulting services to philanthropic foundations in Mexico, including organisational strengthening, gender frameworks, and disaster resilience advisory. She noted that foundations often require support in allocating funds effectively, not just in making donations. The main challenge is cultural, as many foundations still favour visible donations over strategic investments. Ethos recognises that changing this mindset takes time and treats the gradual pace as an inherent cost of innovation."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Anthea described how CIPS anticipated declining aid as Indonesia developed and proactively built corporate partnerships with clear guidelines: limits on government funding, disclaimers for corporate-funded studies, and a focus on projects serving the public interest, such as consumer protection in fintech. Its flagship event, Digiweek, attracts corporate sponsorship in technology policy. Anthea emphasised the importance of respect for institutional independence and for the audience’s intelligence."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"FUSADES underwent significant changes in response to political developments. After policy shifts in El Salvador in 2019, the organisation lost tax incentives and faced increased risks in partnering with private donors. In response, FUSADES established a trust fund, generated rental income, repositioned community leadership programmes as corporate social responsibility initiatives, offered legislative mapping services to corporate lawyers, launched an “AI Academy” focused on AI ethics and data protection, and produced a prime-time television programme on resilience that reached over 1.3 million viewers. The organisation retrained its lawyers as AI experts rather than hiring externally. "}]},{type:a,value:c},{type:b,tag:z,props:{id:t},children:[{type:b,tag:e,props:{href:"#acknowledging-the-risks",ariaHidden:A,tabIndex:B},children:[{type:b,tag:C,props:{className:[D,E]},children:[]}]},{type:a,value:v}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The session did not present diversification as a universal solution and acknowledged the associated risks and challenges."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"One risk is corporate capture. Accepting corporate funding requires clear boundaries, disclosure of sponsorships, and alignment with the organisation’s mission. As Anthea stated, the solution is not to reject corporate funding outright, but to define in advance which activities will not be undertaken in exchange for it."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Another risk relates to the political environment. FUSADES shows that opportunities shift depending on those in power. Certain topics may become inaccessible, and some services must be adapted to remain viable without compromising the mission."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Capacity is often where good ideas for income generation falter. A strong researcher is not always a good trainer, client manager, or commercial project lead. Assuming otherwise can stall new revenue streams. Retraining helps; FUSADES turned lawyers into AI experts, and Ethos developed new skills within existing teams. However, this takes time, and not everyone adapts. Staff burnout is a real cost often overlooked in revenue projections."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A further risk is internal strain. New income streams can raise concerns about commercialisation or mission drift. As Liliana noted, diversification is as much a change-management challenge as an organisational-culture one. Without team support, new services will not succeed. Several speakers emphasised the importance of a clear organisational purpose to safeguard against drifting toward client-driven priorities. Diluting this focus can undermine the brand."}]},{type:a,value:c},{type:b,tag:z,props:{id:w},children:[{type:b,tag:e,props:{href:"#effective-strategies",ariaHidden:A,tabIndex:B},children:[{type:b,tag:C,props:{className:[D,E]},children:[]}]},{type:a,value:x}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"The session highlighted several actionable insights."}]},{type:a,value:c},{type:b,tag:"ul",props:{},children:[{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Leverage existing strengths:"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" IEP’s survey unit, FUSADES’s legal services, and CIPS’s convening capabilities all draw on existing expertise offered to paying clients. Assess your underutilised assets before developing new products."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Emphasise methodological rigour:"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" In a competitive consultancy market, credibility sets a think tank apart. IEP, for example, competes on methodological credibility, academic standards that private firms cannot replicate, and registration with electoral authorities that signals independence. In a market where anyone can run a survey, IEP’s willingness to publish and stand behind its methodology is the product. This applies beyond polling; any service is more valuable when backed by an analytical reputation built over years."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Protecting independence requires mechanisms, not just good intentions:"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" CIPS uses three. First, self-imposed caps: at least 50% of income must come from private philanthropy, and no single corporate or government funder can exceed a set ceiling, ensuring no single actor holds financial leverage. Second, disclosed funding: company sponsorships are openly stated in publications, allowing the public to judge the work on its merits. Third, commercial agnosticism: CIPS never promotes specific companies’ products or services. It addresses macro questions such as regulation, consumer protection, and market design, positioning itself as a voice for the broader environment. These principles are why companies trust CIPS to sponsor events."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Pursue collaboration over competition:"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" Think tanks can share projects, client networks, and expertise rather than building every capability independently. Consortia and joint offers enable smaller organisations to pursue work they could not deliver alone."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:n,props:{},children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Subscriptions and memberships can provide stable income but require active management:"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:" Some participants described models offering exclusive analysis, closed events, and tailored memos. Success depends on delivering consistent, high-quality content and retaining an engaged audience. This is a product management function, not an incidental benefit."}]},{type:a,value:c}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A consistent warning emerged: assess your organisational capacity before launching new income streams. Memberships, training, events, and consultancies may seem attractive, but without adequate team, time, or systems in place, they are unsustainable. Overextension is a greater risk than weak demand. Patience is essential, as these models take years to develop. Ethos, IEP, and FUSADES progressed incrementally."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Funding remains the sector’s primary challenge, as it has for the past decade and likely will continue to. However, this session offered optimism: four organisations in diverse contexts found unique solutions by first assessing their internal strengths. OTT is no exception. The On Think Tanks programme is supported by grants (of various sizes and lengths), participants’ fees for some of our events and courses, consulting projects for think tanks and funders, a new membership model, and an internal subsidy from our consulting profits. That is the conversation worth continuing in the next State of the Sector survey, in our courses, and at future conferences."}]}]},dir:p,path:"\u002Fcolumnas\u002Fhow_four_think_tanks_are_adapting_as_core_funding_declines",extension:q,createdAt:"2026-07-19T00:56:17.187Z",updatedAt:"2026-07-19T00:56:17.188Z"},columnas:[{slug:"collaboration_under_the_mantle_of_populism",title:"Collaboration under the mantle of populism",date:"2025-07-10T17:20:20.737Z",img:"https:\u002F\u002Fucarecdn.com\u002F2c75323d-b65f-4d5a-8e29-fa2c0b7f4977\u002F","img-alt":"colaboración",autor:"Liliana Alvarado ",medio:r,link:"https:\u002F\u002Fonthinktanks.org\u002Farticles\u002Fcollaboration-under-the-mantle-of-populism\u002F",category:o,extracto:F,toc:[],body:{type:m,children:[{type:b,tag:d,props:{},children:[{type:a,value:"In general terms, collaboration involves establishing a relationship with other actors —whether similar or different— with the aim of achieving a specific goal. In order for collaboration to be effective, there are several elements that must be in place: (1) a shared objective, (2) transparent and fluid communication, (3) an environment of mutual trust, and (4) a favorable context. Collaboration tends to be more successful when the benefits are clear or when it addresses a pressing need of the parties involved."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"In practice, the contextual factor has proven to carry significant weight. In the specific case of the Latin American region, some populist governments—whether left- or right-leaning—have sought to divide their populations in various ways (rich vs. poor, right vs. left, liberals vs. conservatives). Generally speaking, these labels have been used by such regimes to separate the “good” from the “bad”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"According to this perspective, the “bad guys” are all those individuals or groups who think differently from the government or ruling party. As a result, criticism of government actions—or demands for openness, transparency, and accountability—can often be met with hostility. This undoubtedly hinders the work of counterweights, which include autonomous or independent entities, the business sector, journalists, and research centres known as think tanks."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"In the case of the organisations mentioned above, they face a twofold challenge that negatively affects their work. The first is the difficulty in maintaining open communication channels, establishing relationships, or collaborating with the current government. This engagement—so crucial for achieving policy impact—becomes nearly impossible. The second issue lies in the difficulty of fostering collaboration among non-governmental actors themselves, such as civil society organisations, the private sector, universities, and the media. All of these stakeholders play a key role in advancing advocacy strategies that seek to drive policy change."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:F}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"At times, the political and economic influence of third countries also affects collaboration. In this regard, funding from international development agencies to think tanks has been shifting significantly over the last few years. In several countries, these funds have been reduced and are now granted for shorter periods, forcing organisations to continually search for resources. This situation was further exacerbated by the “Trump factor,” as the U.S. president had earlier decided to eliminate foreign aid provided by the United States Agency for International Development (USAID) to other countries."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Currently, securing three or four separate funding sources may be necessary to cover what was once achieved with just one. This resource scarcity has made it increasingly difficult to form consortia to access funding. While some donors encourage collaboration among two or more think tanks to design and implement projects, the overall reduction in available resources has made it less feasible to split funding among multiple parties."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"It seems that both national and international contexts are undermining collaborative efforts. In the case of think tanks, this has led to new challenges in how they operate, particularly in certain regions of the world. Yet, working in isolation does not appear to be a viable alternative either. Will it become increasingly common for think tanks to form alliances with actors from opposing ideological backgrounds? Is it possible for civil society organizations to collaborate with governments they do not trust —or that seek to delegitimize their work? Where should we draw the line between a healthy diversity of perspectives and the values that a collaboration can tolerate without compromising its purpose?"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Think tanks are at a crossroads where they must determine whether a less genuine and sincere form of collaboration is still desirable, or at least strategically necessary. This dilemma applies not only to relationships with incumbent governments but also to those with non-governmental actors. Do the ends justify the means? There is no definitive answer. In some cases, populism and its effects have been gradually expanding, prompting think tanks to adapt to shifting dynamics and to test various strategies in an effort to understand what works and what does not."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"It is challenging to predict the future of collaboration under the influence of populism, which is increasingly drawing more people into its sphere. In this context, think tanks must find ways to remain relevant and loyal to their principles, without legitimising positions that are eroding democratic institutions. The challenge lies in not losing sight of what gives meaning to their existence: contributing to the public interest through research and independent thinking."}]}]},dir:p,path:"\u002Fcolumnas\u002Fcollaboration_under_the_mantle_of_populism",extension:q,createdAt:G,updatedAt:G},{slug:"cuatro_formas_creativas_en_las_que_colaboran_los_think_tanks_con_periodistas",title:"CUATRO FORMAS CREATIVAS EN LAS QUE COLABORAN LOS THINK TANKS CON PERIODISTAS ",date:"2018-11-13T00:03:36.335Z",img:"https:\u002F\u002Fucarecdn.com\u002F0cca2aa0-fe73-4d2d-ab07-2ae60d598681\u002F",autor:y,medio:H,link:"https:\u002F\u002Fwww.arenapublica.com\u002Fblog-ethos-laboratorio\u002Fthink-tanks-y-periodistas-4-formas-de-colaboracion",category:o,extracto:"Los *think tanks* a nivel global tenemos problemas para comunicar lo que hacemos. Muchas veces cuando les contamos a nuestros amigos y familiares sobre nuestro trabajo, las reacciones más frecuentes son: “¿*think* qué?”, “¿en qué piensan?”, “¿tanque? debe estar relacionado con las fuerzas armadas”.",toc:[],body:{type:m,children:[{type:b,tag:d,props:{},children:[{type:b,tag:j,props:{},children:[{type:a,value:"Los think tanks se enfrentan al reto de difundir los conocimientos que producen. A través de diversas estrategias innovadoras pueden generar una comunicación efectiva con la sociedad."}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" a nivel global tenemos problemas para comunicar lo que hacemos. Muchas veces cuando les contamos a nuestros amigos y familiares sobre nuestro trabajo, las reacciones más frecuentes son: “¿"},{type:b,tag:j,props:{},children:[{type:a,value:"think"}]},{type:a,value:" qué?”, “¿en qué piensan?”, “¿tanque? debe estar relacionado con las fuerzas armadas”."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A nivel mundial, muchos centros de pensamiento y estudios, organismos de desarrollo y otros, "},{type:b,tag:k,props:{},children:[{type:a,value:"no logramos comunicar el conocimiento que generamos"}]},{type:a,value:". Entre una serie de Netflix, o los feeds de las redes sociales, y un estudio de políticas públicas, ¿qué escogería consumir usted? El Banco Mundial hizo un "},{type:b,tag:e,props:{href:"http:\u002F\u002Fdocuments.worldbank.org\u002Fcurated\u002Fen\u002F387501468322733597\u002Fpdf\u002FWPS6851.pdf",rel:[f,g,h],target:i},children:[{type:a,value:"estudio"}]},{type:a,value:" hace unos años en el que encontró que el 31% de sus documentos nunca habían sido descargados. Y se trata de textos dirigidos a expertos que deberían preferir la lectura de dichos documentos, frente a ver La Casa de las Flores."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Si el Banco Mundial es una de las instituciones con más recursos y especialistas para generar y difundir conocimiento sobre desarrollo económico y político, ¿qué podemos hacer instituciones mucho más pequeñas y sin tantos recursos para llegar a tener más influencia? Felizmente, en México hay muchos casos de innovación que responden cómo hacerlo, provenientes de "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" y organizaciones similares. Se trata de "},{type:b,tag:k,props:{},children:[{type:a,value:"alianzas con medios creativos, trabajo colaborativo con periodistas de investigación, uso de herramientas tecnológicas"}]},{type:a,value:", entre otros. Acá les damos 4 ejemplos sobre cómo lograrlo:"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:I}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“"},{type:b,tag:k,props:{},children:[{type:a,value:"PAOLA"}]},{type:a,value:". Era trabajadora sexual. Fue asesinada hace dos años en el coche de un cliente. "},{type:b,tag:k,props:{},children:[{type:a,value:"El principal sospechoso, un exmilitar, sigue prófugo"}]},{type:a,value:".”"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Para difundir su reporte "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002Fwp-content\u002Fuploads\u002F2018\u002F09\u002F5013HomicidiosCDMX.pdf",rel:[f,g,h],target:i},children:[{type:a,value:I}]},{type:a,value:", "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.mexicoevalua.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"México Evalúa"}]},{type:a,value:" creó una alianza con El País, de lo cual resultó el reportaje "},{type:b,tag:e,props:{href:"https:\u002F\u002Felpais.com\u002Fespeciales\u002F2018\u002Fviolencia-cdmx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Matar o morir"}]},{type:a,value:". La plataforma enlaza testimonios, numeralias, videos, frases y gráficas interactivas, lo que da un sentido más humano al informe."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Asimismo, Fusión generó "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.facebook.com\u002FFusionMexicoOficial\u002Fvideos\u002F732797000392788\u002FUzpfSTEwMDAwMjYzMjY5MjYwODoxNzY0MjUyNjAwMzM5MTQ2\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"minidocumentales"}]},{type:a,value:" y México.com publicó una serie de "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.mexico.com\u002Fespecial\u002Fhomicidios-en-cdmx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"reportajes"}]},{type:a,value:" relacionados con el contenido del informe."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"La Estafa Maestra"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Sabemos que hay muchísima corrupción. Pero como es un fenómeno que se hace a escondidas y se trata de ocultar por todos los medios posibles, no es fácil encontrar sus mecanismos ni descubrirla a la opinión pública. Sin embargo, "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.animalpolitico.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Animal Político"}]},{type:a,value:J},{type:b,tag:e,props:{href:K,rel:[f,g,h],target:i},children:[{type:a,value:L}]},{type:a,value:"(MCCI) hicieron exactamente eso: "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.animalpolitico.com\u002Festafa-maestra\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"revelaron que dependencias del Gobierno Federal"}]},{type:a,value:" y universidades públicas "},{type:b,tag:k,props:{},children:[{type:a,value:"desviaron 7,670 millones de pesos"}]},{type:a,value:" en contratos ilegales a 186 empresas, de la cuales 128 eran empresas fantasma."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"El equipo de periodistas presentó la información con un formato interactivo y transmedia. Empleó videos, testimoniales, un cómic, infografías, numeralias y hasta emojis. Además vincularon a los becarios del programa Prensa y Democracia ("},{type:b,tag:e,props:{href:"https:\u002F\u002Ftwitter.com\u002Fprogramaprende?lang=es",rel:[f,g,h],target:i},children:[{type:a,value:"PRENDE"}]},{type:a,value:") de la "},{type:b,tag:e,props:{href:"http:\u002F\u002Fibero.mx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Universidad Iberoamericana"}]},{type:a,value:" para colaborar en la investigación. Gracias a este trabajo, la Auditoría Superior de la Federación reconoció esta red de corrupción y el Servicio de Administración Tributaria inició una investigación contra empresas fantasma."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:"Por qué se cayó mi edificio"}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"“Los habitantes en la Ciudad de México saben qué hacer durante un sismo; cómo salir de un departamento o dónde resguardarse mejor. Quienes han fallado han sido las autoridades.”"}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"A través de un trabajo colaborativo entre la ciudadanía, investigadores y periodistas, "},{type:b,tag:e,props:{href:K,rel:[f,g,h],target:i},children:[{type:a,value:L}]},{type:a,value:"presentó un "},{type:b,tag:e,props:{href:"https:\u002F\u002Fmiedificio.contralacorrupcion.mx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"micrositio"}]},{type:a,value:" que incluye un "},{type:b,tag:k,props:{},children:[{type:a,value:"recorrido por 28 construcciones"}]},{type:a,value:" en las que se detectaron actos de corrupción. A través de ilustraciones, fotografías y el uso del periodismo narrativo se entiende lo vivido en cada una de ellas.  Y se demuestra que el fallecimiento de muchas personas y daños provocados por el sismo del 19 de septiembre de 2017 pudieron haberse evitado si se respetaran las reglas para realizar construcciones."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:b,tag:k,props:{},children:[{type:a,value:M}]}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"La designación de los funcionarios públicos en México sigue siendo una área gris sobre la que "},{type:b,tag:e,props:{href:"http:\u002F\u002Ffundar.org.mx\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Fundar"}]},{type:a,value:J},{type:b,tag:e,props:{href:"https:\u002F\u002Farticulo19.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Artículo 19"}]},{type:a,value:" pusieron el ojo para tratar de echar abajo “el dedazo” en la asignación de puestos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Desde 2012 y hasta la fecha, activistas, investigadores y periodistas trabajan en el proyecto "},{type:b,tag:e,props:{href:"https:\u002F\u002Fdesignaciones.org\u002Ffederales\u002F#!\u002Fprincipal",rel:[f,g,h],target:i},children:[{type:a,value:M}]},{type:a,value:" para "},{type:b,tag:k,props:{},children:[{type:a,value:"analizar los procesos de selección de los titulares de las instituciones"}]},{type:a,value:". Los objetivos están claros: primero, contar con mayor transparencia y participación ciudadana en los nombramientos; y, segundo, que las personas que ocupan los cargos públicos tengan experiencia y cuenten con capacidad probada en el tema."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Publicado en: "},{type:b,tag:e,props:{href:"https:\u002F\u002Fwww.arenapublica.com\u002Fblog-ethos-laboratorio\u002Fcuatro-formas-creativas-en-las-que-colaboran-los-think-tanks-con-periodistas",rel:[f,g,h],target:i},children:[{type:a,value:H}]}]}]},dir:p,path:"\u002Fcolumnas\u002Fcuatro_formas_creativas_en_las_que_colaboran_los_think_tanks_con_periodistas",extension:q,createdAt:"2023-06-19T05:11:57.687Z",updatedAt:N},{slug:"el_contrapeso_gubernamental_a_la_baja",description:"\nEn términos muy generales, los think tanks son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano.",title:"¿EL CONTRAPESO GUBERNAMENTAL A LA BAJA?",date:"2022-02-22T23:44:29.610Z",img:"https:\u002F\u002Fucarecdn.com\u002F1fd5c811-6354-462c-b33a-04b627a7742d\u002F",autor:"Liliana Alvarado",medio:"El Economista",link:"https:\u002F\u002Fwww.eleconomista.com.mx\u002Fopinion\u002FEl-contrapeso-gubernamental-a-la-baja-20220222-0057.html",category:o,extracto:"En términos muy generales, los *think tanks* son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación",toc:[],body:{type:m,children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:O},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano. "},{type:a,value:" Otra diferencia entre ellos es el tipo de relación que tienen con su respectivo gobierno. En algunos países los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" asesoran y colaboran de forma cercana con las autoridades, pues se valora significativamente su capacidad y conocimiento técnico en las diferentes temáticas. No obstante, en otras naciones los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" adquieren un papel de "},{type:b,tag:j,props:{},children:[{type:a,value:P}]},{type:a,value:", haciendo referencia a la figura de un perro guardián que tiene como objetivo realizar tareas de vigilancia y monitoreo. Es más común que las organizaciones tomen este papel cuando el país enfrenta debilidades importantes en materia de transparencia, rendición de cuentas, anticorrupción, entre otros temas que requieren un señalamiento o voz de denuncia."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"En este sentido, los "},{type:b,tag:j,props:{},children:[{type:a,value:P}]},{type:a,value:" forman parte del conjunto de contrapesos al gobierno. A la lista se suman algunos medios de comunicación, periodistas, el empresariado, los organismos autónomos y electorales, entre otros. No obstante, de esta lista, tal vez uno de los contrapesos menos analizados y conocidos son los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:". Ello se relaciona con el hecho de que su trabajo en ocasiones se confunde con el de la academia o incluso con organizaciones activistas."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Recientemente la plataforma global On Think Tanks presentó el Open Think Tanks Directory, que incluye un documento de análisis sobre los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" en el continente americano. De acuerdo con el reporte, los temas más comunes que abordan las organizaciones en Latinoamérica y el Caribe (LAC) en orden de importancia son: medio ambiente, política social, gobernanza\u002Ftransparencia y justicia\u002Fderechos humanos."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"No sorprende que en nuestra región algunas de las prioridades de las organizaciones sean los temas de gobernanza\u002Ftransparencia así como justicia\u002Fderechos humanos. Los problemas en dichos temas son profundos y se requiere mostrar con datos y evidencia cuáles son las áreas de mejora. Otro dato interesante del reporte se refiere al número de "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" en cada país: Brasil (65), Argentina (54), Chile (52) y México (43). En el otro extremo tenemos a países con un número muy reducido: Honduras (4), Nicaragua (3) y Belice (1). Un análisis más profundo nos permitiría conocer su antigüedad, presupuesto, fuentes de financiamiento, así como valorar el impacto e incidencia que tienen las organizaciones en las políticas públicas del país."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Cuando analizamos la tendencia de "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" creados por década y por región, se aprecia que, tanto en el mundo como en América del Norte y Latinoamérica, la creación de este tipo de instituciones va a la baja. Particularmente, en América Latina y el Caribe, la mayoría de este tipo de organizaciones se crearon entre 1990 y el 2009."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Dado este escenario, la pregunta adecuada sería ¿los think tanks como contrapeso, van a la baja? La respuesta es no. Hoy en día los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" son más necesarios que nunca. En América Latina, por ejemplo, la corrupción no ha ido mejorando y tampoco lo han hecho temas como la seguridad, justicia, defensa de los derechos humanos, entre otros."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Lo que sí ha pasado es que las condiciones en las que trabajan los "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" y otros actores que son contrapeso del gobierno en la región, se han vuelto más difíciles. Actualmente en algunos países se condena a quienes los financian, se persigue a quienes los dirigen y se intimida a sus miembros. En un contexto como este, es fácil entender que Nicaragua, donde el presidente Daniel Ortega ha perseguido a opositores, disidentes y periodistas para mantenerse en el poder, solo tenga tres."}]},{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:"Hoy más que nunca hay que generar conciencia sobre la importancia de estas organizaciones. De manera particular, preocupa que con el paso del tiempo se están creando menos "},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:". Las razones pueden ser diversas, sin embargo, el resultado es el mismo. Existen menos organizaciones en la región que están vigilando el actuar de los gobiernos y que están presionando para contar con mejores democracias, gobernanza y condiciones de vida para la población."}]},{type:a,value:c}]},excerpt:{type:m,children:[{type:a,value:c},{type:b,tag:d,props:{},children:[{type:a,value:O},{type:b,tag:j,props:{},children:[{type:a,value:l}]},{type:a,value:" son centros de investigación que buscan mejoras en las políticas públicas de los distintos países en los que operan. Las diferencias entre éstos son marcadas, pues mientras unos se enfocan en analizar múltiples temas, otros tienen únicamente una línea de investigación. Algunas organizaciones cuentan con cientos de empleados, sin embargo, el equipo de otros apenas se cuenta con los dedos de una mano."}]}]},dir:p,path:"\u002Fcolumnas\u002Fel_contrapeso_gubernamental_a_la_baja",extension:q,createdAt:"2023-06-19T05:11:57.867Z",updatedAt:N}]}],fetch:{},mutations:[]}}("text","element","\n","p","a","nofollow","noopener","noreferrer","_blank","em","strong","think tanks","root","li","think-tanks","\u002Fcolumnas",".md","On Think Tanks","Diversifying income is now essential for survival, not just an option for a select few. Following USAID’s withdrawal and aid reductions, the question has shifted from “should we diversify?” to “how do we diversify?”","acknowledging-the-risks",3,"Acknowledging the risks","effective-strategies","Effective strategies","Ethos","h3","true",-1,"span","icon","icon-link","The radicalisation and polarisation of perspectives hinder dialogue and consensus-building. This growing divide among actors is not only present in populist governments but also in other regimes undergoing processes of democratic backsliding, where core values such as freedom of expression, civic participation, the rule of law, and tolerance are increasingly undermined.","2025-11-25T01:24:03.234Z","Arena Pública","5013 homicidios en la Ciudad de México"," y ","https:\u002F\u002Fcontralacorrupcion.mx\u002F","Mexicanos contra la Corrupción y la Impunidad ","Designaciones públicas","2022-09-15T15:48:00.227Z","En términos muy generales, los ","watch dogs")));